Below is a **complete, self‑contained C++ program** that demonstrates several kinds of operator overloading.  
It defines a tiny 3‑D vector class (`Vector3`) and overloads:

| Operator | What it does in this example |
|----------|------------------------------|
| `+` | Vector addition |
| `-` | Vector subtraction |
| `*` | Dot‑product (scalar multiplication) and also scalar *vector multiplication via a non‑member overload |
| `<<` | Stream insertion (pretty‑printing) |
| `==` | Equality comparison (optional) |
| `[]` | Element access (read/write) |

```cpp
#include <iostream>
#include <iomanip>   // for std::setprecision
#include <stdexcept> // for std::out_of_range

// -----------------------------------------------------------------------------
// 3‑D vector class with operator overloading
// -----------------------------------------------------------------------------
class Vector3
{
private:
    double data[3];          // storage: data[0] = x, data[1] = y, data[2] = z

public:
    // ---------- constructors -----------------------------------------------
    Vector3() : data{0,0,0} {}                      // default = (0,0,0)
    Vector3(double x, double y, double z)          // explicit three‑component ctor
        : data{x, y, z} {}

    // ---------- element access ---------------------------------------------
    double& operator[](std::size_t idx) {
        if (idx >= 3) throw std::out_of_range("Vector3 index out of range");
        return data[idx];
    }
    const double& operator[](std::size_t idx) const {
        if (idx >= 3) throw std::out_of_range("Vector3 index out of range");
        return data[idx];
    }

    // ---------- arithmetic operators ---------------------------------------
    // Vector addition: a + b
    Vector3 operator+(const Vector3& rhs) const {
        return Vector3{ data[0] + rhs.data[0],
                        data[1] + rhs.data[1],
                        data[2] + rhs.data[2] };
    }

    // Vector subtraction: a - b
    Vector3 operator-(const Vector3& rhs) const {
        return Vector3{ data[0] - rhs.data[0],
                        data[1] - rhs.data[1],
                        data[2] - rhs.data[2] };
    }

    // Dot product: a * b (returns a scalar)
    double operator*(const Vector3& rhs) const {
        return data[0] * rhs.data[0] +
               data[1] * rhs.data[1] +
               data[2] * rhs.data[2];
    }

    // Scalar multiplication on the right: a * k
    Vector3 operator*(double scalar) const {
        return Vector3{ data[0] * scalar,
                        data[1] * scalar,
                        data[2] * scalar };
    }

    // ---------- comparison operator ----------------------------------------
    bool operator==(const Vector3& rhs) const {
        return data[0] == rhs.data[0] &&
               data[1] == rhs.data[1] &&
               data[2] == rhs.data[2];
    }

    // ---------- friend functions --------------------------------------------
    // Scalar multiplication on the left: k * a
    friend Vector3 operator*(double scalar, const Vector3& vec) {
        return vec * scalar;            // reuse the member operator
    }

    // Stream insertion: print a Vector3
    friend std::ostream& operator<<(std::ostream& os, const Vector3& v) {
        os << '(' << v.data[0] << ", " << v.data[1] << ", " << v.data[2] << ')';
        return os;
    }
};

// -----------------------------------------------------------------------------
// Demo
// -----------------------------------------------------------------------------
int main()
{
    Vector3 a{1.0, 2.0, 3.0};
    Vector3 b{4.0, 5.0, 6.0};

    std::cout << std::fixed << std::setprecision(2);

    // Vector addition
    Vector3 c = a + b;
    std::cout << "a + b = " << c << '\n';

    // Vector subtraction
    Vector3 d = a - b;
    std::cout << "a - b = " << d << '\n';

    // Dot product
    double dot = a * b;
    std::cout << "a · b = " << dot << '\n';

    // Scalar multiplication
    Vector3 e = a * 2.5;
    std::cout << "a * 2.5 = " << e << '\n';

    // Scalar multiplication with scalar on the left
    Vector3 f = 3.0 * b;
    std::cout << "3.0 * b = " << f << '\n';

    // Element access (modify z‑component)
    a[2] = 10.0;
    std::cout << "After setting a[2] = 10.0, a = " << a << '\n';

    // Equality comparison
    std::cout << "a == b? " << (a == b ? "yes" : "no") << '\n';

    return 0;
}
```

### What the program shows

1. **`operator+` and `operator-`**: These are **member** functions that return a new `Vector3` that is the component‑wise sum or difference of the operands.

2. **`operator*`**:  
   * The **member** overload taking another `Vector3` computes the **dot product** and returns a `double`.  
   * The member overload taking a `double` scales the vector.  
   * A **friend** overload `operator*(double, const Vector3&)` handles the scalar‑on‑the‑left case by delegating to the member overload.

3. **`operator<<`**: A friend function that prints a vector in the form `(x, y, z)`.  
   It must be a friend because it takes the stream as its first argument, not the vector.

4. **`operator[]`**: Provides read/write access to individual components by index.

5. **`operator==`**: Allows simple equality comparison between two vectors.

Compile with a standard‑conforming compiler (e.g., `g++ -std=c++17 main.cpp -o vec`) and run it to see the overloaded operators in action.
